import React, { useState, useEffect, useCallback } from 'react';
import './App.css';

const BACKEND_URL = 'http://localhost:5000/api';

export default function App() {
  // ============ STATE ============
  const [isGhostMode, setIsGhostMode] = useState(true);
  const [calcInput, setCalcInput] = useState('');
  const [calcDisplay, setCalcDisplay] = useState('0');
  const [calcExpression, setCalcExpression] = useState('');
  const [category, setCategory] = useState('Mental Health');
  const [storyText, setStoryText] = useState('');
  const [globalStories, setGlobalStories] = useState([]);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [replyText, setReplyText] = useState('');
  const [replyingTo, setReplyingTo] = useState(null);
  const [showReplies, setShowReplies] = useState({});
  const [replies, setReplies] = useState({});
  const [sosStatus, setSosStatus] = useState('');

  // ============ OFFLINE SYNC ============
  const syncOfflineStories = useCallback(async () => {
    try {
      const offlineData = localStorage.getItem('offlineStories');
      if (!offlineData) return;
      const queue = JSON.parse(offlineData);
      if (queue.length === 0) return;
      for (const story of queue) {
        await fetch(`${BACKEND_URL}/story/save`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(story),
        });
      }
      localStorage.removeItem('offlineStories');
      fetchStories();
      alert('Your offline posts have been successfully synced!');
    } catch (err) {
      console.log('Sync failed.');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============ FETCH STORIES ============
  const fetchStories = useCallback(async () => {
    try {
      const response = await fetch(`${BACKEND_URL}/story/get`);
      const data = await response.json();
      if (data.success) {
        setGlobalStories(data.stories);
        setIsOffline(false);
      }
    } catch (err) {
      setIsOffline(true);
    }
  }, []);

  // ============ ONLINE/OFFLINE LISTENERS ============
  useEffect(() => {
    fetchStories();
    const goOnline = () => {
      setIsOffline(false);
      syncOfflineStories();
    };
    const goOffline = () => setIsOffline(true);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, [fetchStories, syncOfflineStories]);

  // ============ POST STORY ============
  const handlePostStory = async (e) => {
    e.preventDefault();
    if (!storyText.trim()) return;
    const newStory = {
      id: Date.now(),
      story: storyText,
      category: category,
      timestamp: new Date().toISOString(),
      location: 'Anonymous User',
      replies: 0
    };
    if (isOffline) {
      const existingQueue = localStorage.getItem('offlineStories');
      const queue = existingQueue ? JSON.parse(existingQueue) : [];
      queue.push(newStory);
      localStorage.setItem('offlineStories', JSON.stringify(queue));
      alert('Offline mode! Your message will send when reconnected.');
      setStoryText('');
      setGlobalStories(prev => [newStory, ...prev]);
    } else {
      try {
        const response = await fetch(`${BACKEND_URL}/story/save`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(newStory)
        });
        const data = await response.json();
        if (data.success) {
          setStoryText('');
          fetchStories();
        }
      } catch (err) {
        setIsOffline(true);
        const existingQueue = localStorage.getItem('offlineStories');
        const queue = existingQueue ? JSON.parse(existingQueue) : [];
        queue.push(newStory);
        localStorage.setItem('offlineStories', JSON.stringify(queue));
        setStoryText('');
        setGlobalStories(prev => [newStory, ...prev]);
      }
    }
  };

  // ============ REPLY FUNCTIONS (NESTED) ============
  const addReply = (storyId, parentId, text) => {
    const newReply = {
      id: Date.now(),
      text: text,
      parentId: parentId || null,
      timestamp: new Date().toISOString(),
      children: []
    };

    setReplies(prev => {
      const storyReplies = prev[storyId] || [];

      if (!parentId) {
        return {
          ...prev,
          [storyId]: [newReply, ...storyReplies]
        };
      }

      const addChild = (list) => {
        return list.map(reply => {
          if (reply.id === parentId) {
            return {
              ...reply,
              children: [newReply, ...(reply.children || [])]
            };
          }
          if (reply.children) {
            return {
              ...reply,
              children: addChild(reply.children)
            };
          }
          return reply;
        });
      };

      return {
        ...prev,
        [storyId]: addChild(storyReplies)
      };
    });

    setGlobalStories(prev => prev.map(story =>
      story.id === storyId
        ? { ...story, replies: (story.replies || 0) + 1 }
        : story
    ));

    try {
      fetch(`${BACKEND_URL}/story/reply`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          storyId: storyId,
          reply: text,
          parentId: parentId || null
        })
      });
    } catch (err) {
      console.log('Reply saved locally');
    }
  };

  const handleReplySubmit = (storyId) => {
    if (!replyText.trim()) return;
    addReply(storyId, replyingTo === storyId ? null : replyingTo, replyText);
    setReplyText('');
    setReplyingTo(null);
  };

  // ============ RENDER NESTED REPLIES ============
  const renderReplies = (storyId, replyList, depth = 0) => {
    if (!replyList || replyList.length === 0) return null;

    return replyList.map((reply) => (
      <div key={reply.id} style={{ marginLeft: depth > 0 ? '18px' : '0px' }}>
        <div style={styles.replyCard}>
          <div style={styles.replyHeader}>
            <span style={styles.replyAnonymous}>Anonymous supporter</span>
            <span style={styles.replyTime}>{formatMessageTime(reply.timestamp)}</span>
          </div>
          <p style={styles.replyText}>{reply.text}</p>
          <button
            style={styles.nestedReplyButton}
            onClick={() => setReplyingTo(replyingTo === reply.id ? null : reply.id)}
          >
            Reply
          </button>
          {replyingTo === reply.id && (
            <div style={styles.replyInputContainer}>
              <input
                type="text"
                style={styles.replyInput}
                placeholder="Write a reply..."
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleReplySubmit(storyId)}
                autoFocus
              />
              <button style={styles.sendReplyButton} onClick={() => handleReplySubmit(storyId)}>Send</button>
            </div>
          )}
          {reply.children && renderReplies(storyId, reply.children, depth + 1)}
        </div>
      </div>
    ));
  };

  // ============ CALCULATOR FUNCTIONS ============
  const handleCalcPress = (val) => {
    if (val === 'AC') {
      setCalcInput('');
      setCalcDisplay('0');
      setCalcExpression('');
      return;
    }

    if (val === '=') {
      if (calcInput === '9999') {
        setIsGhostMode(false);
        setCalcInput('');
        setCalcDisplay('0');
        setCalcExpression('');
        return;
      }
      try {
        // eslint-disable-next-line no-eval
        const result = eval(calcInput);
        setCalcDisplay(result.toString());
        setCalcExpression(calcInput + ' = ' + result);
        setCalcInput(result.toString());
      } catch {
        setCalcDisplay('Error');
        setCalcInput('');
      }
      return;
    }

    const fnMap = {
      'sin(': 'Math.sin(',
      'cos(': 'Math.cos(',
      'tan(': 'Math.tan(',
      'log(': 'Math.log10(',
      '√(': 'Math.sqrt('
    };
    if (fnMap[val]) {
      setCalcInput(prev => prev + fnMap[val]);
      setCalcDisplay(prev => (prev === '0' ? val : prev + val));
      return;
    }
    if (val === 'π') {
      setCalcInput(prev => prev + Math.PI.toString());
      setCalcDisplay(prev => (prev === '0' ? 'π' : prev + 'π'));
      return;
    }
    if (val === 'e') {
      setCalcInput(prev => prev + Math.E.toString());
      setCalcDisplay(prev => (prev === '0' ? 'e' : prev + 'e'));
      return;
    }

    setCalcInput(prev => prev + val);
    setCalcDisplay(prev => (prev === '0' ? val : prev + val));
  };

  // ============ SOS FUNCTION ============
  const triggerSOS = async () => {
    setSosStatus("SOS triggered. Getting your location...");

    if (!navigator.geolocation) {
      alert('Your browser does not support GPS. Please call 100, 102, or 1145 directly.');
      setSosStatus("Browser doesn't support GPS.");
      return;
    }

    const options = {
      enableHighAccuracy: true,
      timeout: 15000,
      maximumAge: 0
    };

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const lat = position.coords.latitude;
        const lng = position.coords.longitude;
        const locationLink = `https://maps.google.com/?q=${lat},${lng}`;

        const payload = {
          location: { lat: lat, lng: lng },
          contacts: [
            { name: 'Police', phone: '100' },
            { name: 'Ambulance', phone: '102' },
            { name: 'Women\'s Helpline', phone: '1145' }
          ]
        };

        try {
          await fetch(`${BACKEND_URL}/location/alert`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          alert(`Emergency SOS sent.\n\nYour location: ${lat}, ${lng}\n${locationLink}\n\nPolice: 100 | Ambulance: 102 | Women's Helpline: 1145\n\nHelp is on the way.`);
          setSosStatus(`SOS sent. Location found.`);

        } catch (err) {
          alert(`SOS saved. Location: ${lat}, ${lng}\n\nWill send when internet returns.`);
          setSosStatus(`SOS saved offline.`);
        }
      },
      (error) => {
        let errorMsg = "";
        switch (error.code) {
          case error.PERMISSION_DENIED:
            errorMsg = "Location permission denied. Please allow location in browser settings and try again.";
            break;
          case error.POSITION_UNAVAILABLE:
            errorMsg = "GPS signal not found. Please go outside or near a window and try again.";
            break;
          case error.TIMEOUT:
            errorMsg = "GPS is taking too long. Please check your location settings and try again.";
            break;
          default:
            errorMsg = "Could not get your location. Please call 100, 102, or 1145 directly.";
        }
        alert(errorMsg);
        setSosStatus("Could not get location. Please check GPS.");
      },
      options
    );
  };

  // ============ UTILITY FUNCTIONS ============
  const activateGhostMode = () => {
    setStoryText('');
    setIsGhostMode(true);
  };

  const toggleReplies = (storyId) => {
    setShowReplies(prev => ({
      ...prev,
      [storyId]: !prev[storyId]
    }));
  };

  const formatMessageTime = (timestamp) => {
    const date = new Date(timestamp);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  };

  const getCategoryStyle = (category) => {
    if (category === 'Mental Health') return { ...styles.categoryPill, backgroundColor: 'rgba(124,152,133,0.18)', color: '#9DBFA8', border: '1px solid rgba(124,152,133,0.4)' };
    if (category === 'Abuse Support') return { ...styles.categoryPill, backgroundColor: 'rgba(201,112,100,0.18)', color: '#E0958A', border: '1px solid rgba(201,112,100,0.4)' };
    return { ...styles.categoryPill, backgroundColor: 'rgba(212,163,86,0.18)', color: '#E3BC7E', border: '1px solid rgba(212,163,86,0.4)' };
  };

  // ============ RENDER: GHOST CALCULATOR (authentic iOS-style) ============
  if (isGhostMode) {
    const fnRow1 = ['sin(', 'cos(', 'tan(', 'log(', '√('];
    const fnRow2 = ['π', 'e', '(', ')', 'AC'];

    return (
      <div style={styles.calcPage}>
        <div style={styles.calcDeviceFrame}>
          <div style={styles.calcScreen}>
            <div style={styles.calcExpression}>{calcExpression || '\u00A0'}</div>
            <div style={styles.calcDisplay}>{calcDisplay}</div>
          </div>

          <div style={styles.calcFnGrid}>
            <div style={styles.calcRow}>
              {fnRow1.map((v) => (
                <button key={v} style={styles.calcFnKey} onClick={() => handleCalcPress(v)}>
                  {v.replace('(', '')}
                </button>
              ))}
            </div>
            <div style={styles.calcRow}>
              {fnRow2.map((v) => (
                <button
                  key={v}
                  style={v === 'AC' ? { ...styles.calcFnKey, ...styles.calcAcKey } : styles.calcFnKey}
                  onClick={() => handleCalcPress(v)}
                >
                  {v}
                </button>
              ))}
            </div>
          </div>

          <div style={styles.calcMainGrid}>
            <div style={styles.calcRow}>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('7')}>7</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('8')}>8</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('9')}>9</button>
              <button style={styles.calcOpKey} onClick={() => handleCalcPress('/')}>÷</button>
            </div>
            <div style={styles.calcRow}>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('4')}>4</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('5')}>5</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('6')}>6</button>
              <button style={styles.calcOpKey} onClick={() => handleCalcPress('*')}>×</button>
            </div>
            <div style={styles.calcRow}>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('1')}>1</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('2')}>2</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('3')}>3</button>
              <button style={styles.calcOpKey} onClick={() => handleCalcPress('-')}>−</button>
            </div>
            <div style={styles.calcRow}>
              <button style={{ ...styles.calcNumKey, ...styles.calcZeroKey }} onClick={() => handleCalcPress('0')}>0</button>
              <button style={styles.calcNumKey} onClick={() => handleCalcPress('.')}>.</button>
              <button style={styles.calcOpKey} onClick={() => handleCalcPress('=')}>=</button>
              <button style={styles.calcOpKey} onClick={() => handleCalcPress('+')}>+</button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // ============ RENDER: MAIN APP ============
  return (
    <div style={styles.appContainer}>
      <div style={styles.ghostBar} onClick={activateGhostMode}>
        <span>Minimize to calculator</span>
      </div>
      {isOffline && (
        <div style={styles.offlineBanner}>
          You're offline — messages will send once you're back online.
        </div>
      )}
      <main style={styles.mainLayout}>
        <header style={styles.headerBlock}>
          <p style={styles.eyebrow}>Anonymous · Encrypted-feeling · Yours</p>
          <h1 style={styles.mainHeading}>Aura</h1>
          <p style={styles.subheading}>A quiet place to put down what you're carrying.</p>
        </header>

        <section style={styles.panel}>
          <h3 style={styles.panelTitle}>Share, with no name attached</h3>
          <div style={styles.categoryRow}>
            {['Mental Health', 'Abuse Support', 'Bullying'].map((cat) => (
              <button
                key={cat}
                style={{ ...styles.catBtn, ...(category === cat ? styles.catBtnActive : {}) }}
                onClick={() => setCategory(cat)}
              >
                {cat}
              </button>
            ))}
          </div>
          <form onSubmit={handlePostStory}>
            <textarea
              style={styles.textArea}
              placeholder="What burdens are you holding today? No identities tracked here..."
              value={storyText}
              onChange={(e) => setStoryText(e.target.value)}
              rows="3"
            />
            <button type="submit" style={styles.submitBtn}>
              Publish story
            </button>
          </form>
        </section>

        <section style={{ marginTop: '36px' }}>
          <h2 style={styles.sectionTitle}>Shared journeys</h2>
          {globalStories.length === 0 ? (
            <p style={styles.emptyState}>No stories yet. Be the first to share.</p>
          ) : (
            globalStories.map((item) => (
              <div key={item.id} style={styles.storyCard}>
                <div style={styles.storyHeader}>
                  <span style={getCategoryStyle(item.category)}>{item.category}</span>
                  <small style={styles.storyTime}>{formatMessageTime(item.timestamp)}</small>
                </div>
                <p style={styles.storyText}>{item.story}</p>
                <div style={styles.storyActions}>
                  <button style={styles.replyButton} onClick={() => setReplyingTo(replyingTo === item.id ? null : item.id)}>
                    Reply · {replies[item.id]?.length || item.replies || 0}
                  </button>
                  <button style={styles.viewRepliesButton} onClick={() => toggleReplies(item.id)}>
                    {showReplies[item.id] ? 'Hide replies' : 'View replies'}
                  </button>
                </div>
                {replyingTo === item.id && (
                  <div style={styles.replyInputContainer}>
                    <input
                      type="text"
                      style={styles.replyInput}
                      placeholder="Write a reply..."
                      value={replyText}
                      onChange={(e) => setReplyText(e.target.value)}
                      onKeyPress={(e) => e.key === 'Enter' && handleReplySubmit(item.id)}
                      autoFocus
                    />
                    <button style={styles.sendReplyButton} onClick={() => handleReplySubmit(item.id)}>Send</button>
                  </div>
                )}
                {showReplies[item.id] && replies[item.id] && replies[item.id].length > 0 && (
                  <div style={styles.repliesSection}>
                    {renderReplies(item.id, replies[item.id])}
                  </div>
                )}
              </div>
            ))
          )}
        </section>
      </main>
      <footer style={styles.sosFooter} onClick={triggerSOS}>
        Trigger emergency SOS
      </footer>
    </div>
  );
}

// ============ STYLES ============
const ink = '#F2ECE3';
const rose = '#C97064';
const sage = '#7C9885';
const card = '#241E1A';
const bg = '#171310';
const line = '#3A322B';

const styles = {
  // ---- Sanctuary app ----
  appContainer: { backgroundColor: bg, minHeight: '100vh', color: ink, fontFamily: "'Segoe UI', -apple-system, sans-serif" },
  ghostBar: { backgroundColor: '#100D0B', color: '#8A7F73', fontSize: '11px', textAlign: 'center', padding: '8px', cursor: 'pointer', userSelect: 'none', letterSpacing: '0.04em' },
  offlineBanner: { backgroundColor: '#4A3620', color: '#F3D9A8', fontSize: '13px', textAlign: 'center', padding: '10px' },
  mainLayout: { maxWidth: '600px', margin: '0 auto', padding: '32px 20px 110px 20px' },
  headerBlock: { marginBottom: '28px' },
  eyebrow: { color: '#8A7F73', fontSize: '11px', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: '10px' },
  mainHeading: { fontSize: '2.4rem', fontWeight: 700, margin: 0, color: ink, letterSpacing: '-0.02em' },
  subheading: { color: '#B4A99C', fontSize: '14px', marginTop: '8px' },
  panel: { backgroundColor: card, borderRadius: '16px', padding: '22px', border: `1px solid ${line}` },
  panelTitle: { marginTop: 0, marginBottom: '14px', color: ink, fontSize: '15px', fontWeight: 600 },
  categoryRow: { display: 'flex', gap: '8px', marginBottom: '16px', flexWrap: 'wrap' },
  catBtn: { flex: '1 1 auto', padding: '9px 10px', border: `1px solid ${line}`, backgroundColor: 'transparent', color: '#B4A99C', borderRadius: '10px', cursor: 'pointer', fontSize: '12.5px' },
  catBtnActive: { backgroundColor: rose, color: '#1A1310', borderColor: rose, fontWeight: 700 },
  textArea: { width: '100%', boxSizing: 'border-box', backgroundColor: '#1D1713', border: `1px solid ${line}`, borderRadius: '12px', padding: '13px', color: ink, resize: 'vertical', fontFamily: 'inherit', fontSize: '14px' },
  submitBtn: { width: '100%', marginTop: '12px', padding: '13px', border: 'none', borderRadius: '12px', backgroundColor: sage, color: '#12201A', fontWeight: 700, cursor: 'pointer', fontSize: '14px' },
  sectionTitle: { color: '#B4A99C', fontSize: '1.05rem', fontWeight: 600, marginBottom: '12px' },
  emptyState: { color: '#6E6259' },
  storyCard: { backgroundColor: card, padding: '18px', borderRadius: '16px', margin: '14px 0', borderLeft: `3px solid ${rose}` },
  storyHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' },
  categoryPill: { padding: '3px 10px', borderRadius: '20px', fontSize: '10.5px', fontWeight: 600 },
  storyTime: { color: '#6E6259', fontSize: '10.5px' },
  storyText: { margin: '6px 0 14px 0', color: '#E6DFD5', fontSize: '14.5px', lineHeight: '1.55' },
  storyActions: { display: 'flex', gap: '18px', borderTop: `1px solid ${line}`, paddingTop: '12px' },
  replyButton: { background: 'none', border: 'none', color: '#B4A99C', fontSize: '12.5px', cursor: 'pointer', padding: '4px 0' },
  viewRepliesButton: { background: 'none', border: 'none', color: rose, fontSize: '12.5px', cursor: 'pointer', padding: '4px 0', fontWeight: 600 },
  replyInputContainer: { display: 'flex', gap: '8px', marginTop: '14px' },
  replyInput: { flex: 1, padding: '10px 14px', borderRadius: '20px', border: `1px solid ${line}`, backgroundColor: '#1D1713', color: '#fff', fontSize: '12.5px', outline: 'none' },
  sendReplyButton: { backgroundColor: rose, border: 'none', padding: '10px 18px', borderRadius: '20px', color: '#1A1310', fontSize: '12.5px', fontWeight: 700, cursor: 'pointer' },
  repliesSection: { marginTop: '14px' },
  replyCard: { backgroundColor: '#1A1512', borderRadius: '12px', padding: '12px 14px', marginTop: '8px', borderLeft: `2px solid ${sage}` },
  replyHeader: { display: 'flex', justifyContent: 'space-between', marginBottom: '6px' },
  replyAnonymous: { fontSize: '10.5px', color: sage, fontWeight: 600 },
  replyTime: { fontSize: '9.5px', color: '#6E6259' },
  replyText: { fontSize: '13px', color: '#D8CFC4', margin: 0, lineHeight: '1.5' },
  nestedReplyButton: { background: 'none', border: 'none', color: rose, fontSize: '11px', cursor: 'pointer', padding: '6px 0 0 0', fontWeight: 600 },
  sosFooter: { position: 'fixed', bottom: 0, left: 0, right: 0, backgroundColor: '#B3261E', color: '#fff', textAlign: 'center', padding: '18px', fontWeight: 700, fontSize: '1rem', cursor: 'pointer', letterSpacing: '0.04em', boxShadow: '0 -6px 16px rgba(0,0,0,0.35)' },

  // ---- Authentic iOS-style calculator disguise ----
  calcPage: { backgroundColor: '#000', minHeight: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '20px' },
  calcDeviceFrame: { width: '320px', maxWidth: '100%', display: 'flex', flexDirection: 'column', gap: '18px' },
  calcScreen: { color: '#fff', textAlign: 'right', padding: '10px 12px 4px' },
  calcExpression: { fontSize: '15px', color: '#6B6B6B', minHeight: '20px', fontFamily: "-apple-system, 'Helvetica Neue', sans-serif" },
  calcDisplay: { fontSize: '3.4rem', color: '#fff', fontWeight: 300, fontFamily: "-apple-system, 'Helvetica Neue', sans-serif", lineHeight: 1.1, wordBreak: 'break-all' },
  calcFnGrid: { display: 'flex', flexDirection: 'column', gap: '10px' },
  calcMainGrid: { display: 'flex', flexDirection: 'column', gap: '10px' },
  calcRow: { display: 'flex', gap: '10px' },
  calcFnKey: { flex: 1, height: '46px', borderRadius: '23px', border: 'none', backgroundColor: '#3A3A3C', color: '#fff', fontSize: '0.92rem', cursor: 'pointer', fontFamily: "-apple-system, sans-serif" },
  calcAcKey: { backgroundColor: '#A5A5A5', color: '#000', fontWeight: 600 },
  calcNumKey: { flex: 1, height: '66px', borderRadius: '33px', border: 'none', backgroundColor: '#333333', color: '#fff', fontSize: '1.6rem', cursor: 'pointer', fontFamily: "-apple-system, sans-serif" },
  calcZeroKey: { flex: 2.16, borderRadius: '33px', textAlign: 'left', paddingLeft: '26px' },
  calcOpKey: { flex: 1, height: '66px', borderRadius: '33px', border: 'none', backgroundColor: '#FF9F0A', color: '#fff', fontSize: '1.7rem', cursor: 'pointer', fontFamily: "-apple-system, sans-serif" },
};
